package com.guocheng.mediapocket;
import android.app.Activity;import android.content.Intent;import android.widget.Toast;
/** 外部视频进入现有播放链：组装 stream / meta 后打开 PlayerActivity。 */
public final class ExternalPlayActivity extends Activity {
 @Override protected void onCreate(android.os.Bundle saved){super.onCreate(saved);try{Intent source=getIntent();android.net.Uri data=source==null?null:source.getData();String raw=data==null?null:data.toString();String mime=source==null?null:source.getType();String title=source==null?null:source.getStringExtra(Intent.EXTRA_TITLE);if(!ExternalPlayRules.playable("android.intent.action.VIEW",raw,mime)){Toast.makeText(this,"这个地址不能用随影播放",Toast.LENGTH_LONG).show();finish();return;}String name=ExternalPlayRules.title(raw,title);org.json.JSONObject stream=ExternalPlayRules.stream(raw,name,source.getStringArrayExtra("headers"));org.json.JSONObject meta=new org.json.JSONObject().put("name",name).put("id",ExternalPlayRules.watchId(raw));Intent play=new Intent(this,PlayerActivity.class);play.putExtra("stream",stream.toString());play.putExtra("sources",new org.json.JSONArray().put(stream).toString());play.putExtra("id",meta.optString("id"));play.putExtra("type","movie");play.putExtra("meta",meta.toString());play.putExtra("name",name);play.putExtra("addons",getSharedPreferences("data",0).getString("addons","[]"));startActivity(play);}catch(Exception e){Toast.makeText(this,"无法打开这个视频",Toast.LENGTH_LONG).show();}finish();}
}
